  438:     @Nullable
  439:     public HalPropValue getIfAvailableOrFail(int propertyId, int numberOfRetries) {
  440:         if (!isPropertySupported(propertyId)) {
  441:             return null;
  442:         }
  443:         Exception lastException = null;
  444:         for (int i = 0; i < numberOfRetries; i++) {
  445:             try {
  446:                 return get(propertyId);
