  448:                 Slogf.w(CarLog.TAG_HAL, "Cannot get " + toCarPropertyLog(propertyId), e);
  449:                 lastException = e;
  450:             }
  451:         }
  452:         throw new IllegalStateException("Cannot get property: 0x" + toHexString(propertyId)
  453:                 + " after " + numberOfRetries + " retries" + ", last exception: "
  454:                 + lastException);
  455:     }
