  543:         } else if (clazz == Boolean.class || clazz == boolean.class) {
  544:             Boolean value = Boolean.valueOf(propValue.getInt32Value(0) == 1);
  545:             return (T) value;
  546:         } else if (clazz == Float.class || clazz == float.class) {
  547:             Float value = propValue.getFloatValue(0);
